arreglo_minimo.1_la_causa:
En src/widgets.ts, rutaAbsoluta:

function rutaAbsoluta(fuente: string): string | null {
  if (/^(https?|data|blob):/i.test(fuente)) return null
  if (/^([a-z]:[\\/]|\\\\)/i.test(fuente)) return fuente
  const base = carpetaActual()
  if (!base) return null
  // Un '%' suelto es legal en un nombre de archivo de Windows: si no se puede
  // decodificar, la cadena va tal cual en vez de tumbar el panel.
  let limpia: string
  try { limpia = decodeURI(fuente) } catch { limpia = fuente }
  return base + '\\' + limpia.replace(/\//g, '\\')
}

arreglo_minimo.2_el_cinturon:
Ningun toDOM debe poder tumbar el panel. En src/widgets.ts, renombrar el cuerpo actual de WidgetImagen.toDOM a `private dibujar(vista: EditorView)` y dejar:

  toDOM(vista: EditorView) {
    try {
      return this.dibujar(vista)
    } catch (e) {
      const caja = document.createElement('div')
      caja.className = 'mf-w mf-w-imagen mf-w-rota'
      caja.textContent = 'No se pudo mostrar la imagen: ' + String(e)
      return caja
    }
  }

Conviene el mismo envoltorio en WidgetTabla, WidgetMermaid, WidgetMate y WidgetCasilla: es la unica frontera donde una excepcion de contenido se convierte en fallo de la vista.

arreglo_minimo.codigo:
En src/preferencias.ts, sanear al leer en vez de parchear la linea 146:

const UNO_DE = <T extends string>(v: unknown, ops: readonly T[], porOmision: T): T =>
  (ops as readonly string[]).includes(v as string) ? (v as T) : porOmision

const NUM = (v: unknown, min: number, max: number, porOmision: number): number =>
  typeof v === 'number' && Number.isFinite(v) && v >= min && v <= max ? v : porOmision

/** Lo guardado es dato ajeno: se acepta lo que se reconoce y lo demas vuelve a fabrica. */
function sanear(g: Record<string, unknown>): Preferencias {
  const p = { ...DE_FABRICA, ...g } as Preferencias
  return {
    ...p,
    tema: UNO_DE(p.tema, ['sistema', 'claro', 'oscuro'] as const, DE_FABRICA.tema),
    profundidad: UNO_DE(p.profundidad, ['suave', 'normal', 'profundo'] as const, DE_FABRICA.profundidad),
    paleta: UNO_DE(p.paleta, ['tinta', 'notas', 'sobria'] as const, DE_FABRICA.paleta),
    sangria: UNO_DE(p.sangria, ['2', '4', 'tab'] as const, DE_FABRICA.sangria),
    modo: UNO_DE(p.modo, ['fuente', 'ambos', 'presentacion'] as const, DE_FABRICA.modo),
    tamano: NUM(p.tamano, 8, 48, DE_FABRICA.tamano),
    interlineado: NUM(p.interlineado, 1, 3, DE_FABRICA.interlineado),
    ancho: NUM(p.ancho, 0, 200, DE_FABRICA.ancho),
    division: NUM(p.division, 0.05, 0.95, DE_FABRICA.division),
    ultimoArchivo: typeof p.ultimoArchivo === 'string' ? p.ultimoArchivo : null,
  }
}

export function leer(): Preferencias {
  try {
    const crudo = localStorage.getItem(CLAVE)
    if (!crudo) return { ...DE_FABRICA }
    const g = JSON.parse(crudo)
    return sanear(g && typeof g === 'object' ? g : {})
  } catch {
    return { ...DE_FABRICA }
  }
}

arreglo_minimo.1_csp_y_protocolo_de_recursos:
src-tauri/tauri.conf.json, bloque app.security:

"security": {
  "csp": "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob: https:; font-src 'self' data:; connect-src 'self' ipc: http://ipc.localhost; object-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'",
  "assetProtocol": { "enable": false, "scope": [] }
}

Notas de por que asi: data: en img-src es obligatorio (leer_imagen devuelve data:...;base64, lib.rs:161); 'unsafe-inline' en style-src es obligatorio por como CodeMirror, KaTeX y Mermaid inyectan estilo; https: en img-src conserva la funcion de imagenes remotas, cuyo control real es la compuerta de widgets.ts:209, no la CSP. NO VERIFICADO: no compile ni corri la aplicacion, asi que esta CSP hay que probarla con `npm run tauri dev` y con el binario empaquetado antes de darla por buena; si dev se queja, usar devCsp aparte en vez de aflojar la de produccion.
